    <!-- MVU Data Binding Script (Phase 2 + Locale) -->
    <script type="module">

        // --- FF+MVU StatusMenu lifecycle: keep only the two newest rendered instances ---
        (() => {
            try {
                if (!window.parent || window.parent === window || !window.frameElement) return;

                const currentFrame = window.frameElement;
                currentFrame.dataset.ffmvuStatusmenuInstance = '1';

                const parentDoc = window.parent.document;
                const statusFrames = Array.from(parentDoc.querySelectorAll('iframe')).filter(frame => {
                    if (!frame.isConnected) return false;
                    if (frame.dataset.ffmvuStatusmenuInstance === '1') return true;
                    try {
                        const doc = frame.contentDocument;
                        return !!(
                            doc &&
                            doc.title === 'AntiGravity Status' &&
                            doc.querySelector('.status-container')
                        );
                    } catch (_) {
                        return false;
                    }
                });

                // querySelectorAll preserves document/message order: keep the newest two.
                for (const oldFrame of statusFrames.slice(0, -2)) {
                    try {
                        oldFrame.dataset.ffmvuStatusmenuRetired = '1';
                        oldFrame.remove();
                    } catch (_) {}
                }
            } catch (_) {}
        })();


