const isTuple = (v) => Array.isArray(v) && v.length >= 2 && typeof v[1] === 'string';
const tupleVal = (v) => isTuple(v) ? v[0] : v;

// --- Helper Functions ---
const _ = (typeof window.parent !== 'undefined' && window.parent._) ? window.parent._ : (window._ ? window._ : null);

const getRaw = (obj, path, def) => {
    if (!obj) return def;
    if (!path) return obj;

    // Native Lodash support (Robust path handling)
    if (_ && _.get) {
        return _.get(obj, path, def);
    }

    // Fallback
    const parts = path.split('.');
    let cur = obj;
    for (const p of parts) {
        if (cur === undefined || cur === null) return def;
        cur = cur[p];
    }
    return (cur === undefined || cur === null) ? def : cur;
};

const getV = (obj, path, def) => {
     const val = getRaw(obj, path, def);
     if (isTuple(val)) return val[0];
     return val;
};

const getListData = (obj, path, def) => {
    const raw = getRaw(obj, path, def);

    // 1. Explicit Schema Override: If user marked as Collection (Record), force it to be a List.
    // Schema paths start with '.', so we check both 'path' and '.path'
    if (COLLECTION_PATHS.has(path) || COLLECTION_PATHS.has('.' + path)) {
        return raw;
    }

    // 2. Strict Mode: No Heuristics. 
    // If it's a tuple [List, Label], we return it as-is.
    // User must target 'path.0' or use Schema to control structure.
    return raw;
};

const getL = (obj, path, def) => {
    const val = getRaw(obj, path, def);
    if (isTuple(val)) return val[1];
    return def; 
};

const formatValue = (val) => {
    if (val === null || val === undefined) return LOCALE.empty_none;
    if (isTuple(val)) return formatValue(tupleVal(val));
    if (Array.isArray(val)) return JSON.stringify(val);
    if (typeof val === 'object') {
        if (val.Desc !== undefined) return formatValue(val.Desc);
        if (val.description !== undefined) return formatValue(val.description);
        if (val.name !== undefined) return formatValue(val.name);
        return null; 
    }
    return val;
};

const tupleLabel = (v, fallback) => isTuple(v) ? (v[1] || fallback) : fallback;

const setVal = (obj, path, newVal) => {
    const raw = getRaw(obj, path);
    if (isTuple(raw)) {
        if (_ && _.set) _.set(obj, path, [newVal, raw[1]]);
        else {
            const parts = path.split('.');
            let cur = obj;
            for (let i = 0; i < parts.length - 1; i++) cur = cur[parts[i]];
            cur[parts[parts.length - 1]] = [newVal, raw[1]];
        }
    } else {
        if (_ && _.set) _.set(obj, path, newVal);
        else {
            const parts = path.split('.');
            let cur = obj;
            for (let i = 0; i < parts.length - 1; i++) cur = cur[parts[i]];
            cur[parts[parts.length - 1]] = newVal;
        }
    }
};

        /**
 * Global Recalculation Hook
 * This function is called whenever an item is equipped or unequipped.
 * Use it to calculate derived stats (HP, MP, Attack, etc) based on base attributes.
 */
window.recalculateDerivedStats = function(charObj) {
    if (!charObj) return;
    console.log("Recalculating stats for:", charObj.Name);

    // Default Example logic (Antigravity System)
    const Lvl = getV(charObj, 'Level', 1);
    const Con = getV(charObj, 'Constitution', 0);
    const Str = getV(charObj, 'Strength', 0);
    const Agi = getV(charObj, 'Agility', 0);
    const Int = getV(charObj, 'Intelligence', 0);
    const Wis = getV(charObj, 'Wisdom', 0);

    // Flat Bonuses from Equipment
    let eqHP = 0, eqMP = 0, eqPAtk = 0, eqMAtk = 0, eqPDef = 0, eqMDef = 0;
    if (charObj.Equipment) {
        for (const item of Object.values(charObj.Equipment)) {
            if (item && typeof item === 'object') {
                eqHP   += Number(item.MaxHPBonus || 0);
                eqMP   += Number(item.MaxMPBonus || 0);
                eqPAtk += Number(item.WeaponDamage || 0);
                eqMAtk += Number(item.WeaponMagDamage || 0);
                eqPDef += Number(item.ArmorPDefBonus || 0);
                eqMDef += Number(item.ArmorMDefBonus || 0);
            }
        }
    }

    const oldMaxHp = getV(charObj, 'Hp_max', 0);
    const oldMaxMp = getV(charObj, 'Mp_max', 0);
    const oldMaxSta = getV(charObj, 'Sta_max', 0);

    // Apply Formulas
    const Hp_max  = Math.floor(20 + (Con * 3) + (Lvl * 6)) + eqHP;
    const Sta_max = Math.floor(50 + (Con * 3) + (Agi * 2) + Math.floor((Lvl * 5) / 3));
    const Mp_max  = Math.floor((50 + (Int * 4) + (Wis * 2) + (Lvl * 5)) / 3) + eqMP;

    const P_Atk = Math.floor((Str * 2) + (Lvl * 2)) + eqPAtk;
    const M_Atk = Math.floor((Int * 2) + (Lvl * 2)) + eqMAtk;
    const P_Def = Math.floor((Con / 2) + (Lvl * 3)) + eqPDef;
    const M_Def = Math.floor((Wis / 2) + (Lvl * 3)) + eqMDef;
    const M_Ast = Math.floor((Wis * 1.5) + (Int * 0.5) + (Lvl * 1.5));

    // Set Values
    setVal(charObj, 'Hp_max', Hp_max);
    setVal(charObj, 'Mp_max', Mp_max);
    setVal(charObj, 'Sta_max', Sta_max);
    setVal(charObj, 'Physical_attack', P_Atk);
    setVal(charObj, 'Magic_attack', M_Atk);
    setVal(charObj, 'Physical_defense', P_Def);
    setVal(charObj, 'Magic_defense', M_Def);
    setVal(charObj, 'Magic_assist', M_Ast);

    // Bounds/Healing on Level Up
    if (oldMaxHp > 0) setVal(charObj, 'Hp_curr', Math.max(0, getV(charObj, 'Hp_curr', 0) + (Hp_max - oldMaxHp)));
    if (oldMaxMp > 0) setVal(charObj, 'Mp_curr', Math.max(0, getV(charObj, 'Mp_curr', 0) + (Mp_max - oldMaxMp)));
    if (oldMaxSta > 0) setVal(charObj, 'Sta_curr', Math.max(0, getV(charObj, 'Sta_curr', 0) + (Sta_max - oldMaxSta)));

    // Ensure current < max
    if (getV(charObj, 'Hp_curr', 0) > Hp_max) setVal(charObj, 'Hp_curr', Hp_max);
    if (getV(charObj, 'Mp_curr', 0) > Mp_max) setVal(charObj, 'Mp_curr', Mp_max);
    if (getV(charObj, 'Sta_curr', 0) > Sta_max) setVal(charObj, 'Sta_curr', Sta_max);
};

        ﻿// Helper to extract Name/Qty from various object keys (ported from Builder)
function getItemSummary(item) {
    if (typeof item !== 'object' || !item) return { name: String(item), qty: '' };

    // Heuristics for Name (dictionary key is already promoted to Name by flatten())
    const nameKeys = ['Name', 'name'];
    let name = 'Item';
    for (const k of nameKeys) {
        if (item[k]) { name = item[k]; break; }
    }

    // Heuristics for Quantity
    const qtyKeys = ['Qty', 'qty'];
    let qty = '';
    for (const k of qtyKeys) {
        if (item[k] !== undefined) { qty = String(item[k]); break; }
    }

    return { name, qty };
}

// Delete List Item with confirmation
function deleteListItem(listPath, itemKey) {
    // console.log('[MZSMB] [deleteListItem] Path:', listPath, 'Key:', itemKey);

    const confirmed = confirm('Delete "' + itemKey + '"?\n\nAre you sure you want to delete this item?');
    if (!confirmed) return;

    // Get current stat_data from _lastStatData (which is kept in sync)
    if (!_lastStatData) {
        console.error('No stat data available');
        return;
    }

    // Navigate to the list in _lastStatData using the full path
    const parts = listPath.split('.').filter(p => p);
    let target = _lastStatData;
    for (let i = 0; i < parts.length; i++) {
        if (target && parts[i] && target[parts[i]] !== undefined) {
            target = target[parts[i]];
        } else {
            console.error('[MZSMB][deleteListItem] Navigation failed at:', parts[i], 'Full path:', listPath);
            return;
        }
    }

    console.log('[MZSMB] [deleteListItem] Target object keys:', Object.keys(target || {}));
    console.log('[MZSMB] [deleteListItem] Looking for itemKey:', itemKey, 'HasOwn:', target && (itemKey in target));

    if (target && typeof target === 'object' && itemKey in target) {
        delete target[itemKey];
        console.log('[MZSMB] [deleteListItem] Deleted successfully');

        // Re-render the UI
        updateStatusPanel({ stat_data: _lastStatData });

        // Save to SillyTavern
        saveStatData(_lastStatData);
    } else {
        console.error('[MZSMB] [deleteListItem] Item not found. Target:', target, 'Key:', itemKey);
        if (target && typeof target === 'object') {
            console.log('[MZSMB] [deleteListItem] Available keys:', Object.keys(target));
        }
    }
}

// --- Pagination State ---
const _listPageState = new Map(); // Store current page per container ID
const _blockPageState = new Map(); // Store current page per block container

// ============================================
// PAGE SIZE CONFIGURATION (Change these values as needed)
// ============================================
const LIST_PAGE_SIZE = 5;   // For QuestList (simple/quest templates)
const BLOCK_PAGE_SIZE = 5;  // For Familiar-type blocks
// ============================================

// --- Merged Generic List Renderer (with Pagination) ---
function renderTemplateList(containerOrId, data, templateId, emptyText = LOCALE.empty_none, shouldFlatten = false, rootData) {
     const container = typeof containerOrId === 'string' ? document.getElementById(containerOrId) : containerOrId;
     if (!container) return;

     // Get container ID for pagination state
     const containerId = container.id || containerOrId;

     // Reset container style/class
     container.innerHTML = '';
     container.className = ''; 
     container.removeAttribute('style');

     // Handle Grid View specific styling (legacy support for existing CSS)
     if (templateId === 'tmpl-grid') {
         container.className = 'list-grid-view'; 
     } else if (templateId === 'tmpl-inventory') {
         container.className = 'list-inventory-view';
     }

     // 1. Prepare Items
     let items = [];

     if (!data || Object.keys(data).length === 0) {
         // Empty State
     } else {
         if (shouldFlatten) {
             // Flattening Logic (for Grid)
             function flatten(obj) {
                 let res = [];
                 if (!obj || typeof obj !== 'object') return res;
                 for (const [key, value] of Object.entries(obj)) {
                     if (key === '$meta' || key === '$key' || key === 'template' || value === null || value === undefined) continue;
                     const unwrapped = isTuple(value) ? tupleVal(value) : value;
                     if (unwrapped === null || unwrapped === undefined) continue;

                     if (typeof unwrapped === 'object' && !Array.isArray(unwrapped)) {
                         // Use dictionary key as Name when item lacks its own Name/name
                         const hasName = unwrapped.Name || unwrapped.name ;
                         // Dictionary key MUST be the source of truth for $key (place it last so it overwrites any $key in unwrapped)
                         res.push({ ...(!hasName ? { Name: key } : {}), ...unwrapped, $key: key });
                     } else {
                         res.push({ name: isTuple(value) ? tupleLabel(value, key) : key, quantity: unwrapped });
                     }
                 }
                 return res;
             }
             items = flatten(data);
         } else {
             // Direct mapping (for Simple/Quest)
             for (const [key, raw] of Object.entries(data)) {
                 if (key === '$meta' || key === '$key' || key === 'template') continue;
                 items.push({ $key: key, $raw: raw });
             }
         }
     }

     if (items.length === 0) { 
         container.innerHTML = '<div style="text-align:center; color:var(--text-secondary); padding:10px;">' + emptyText + '</div>';
         if (templateId === 'tmpl-grid' || templateId === 'tmpl-inventory') {
              container.innerHTML = '<div style="grid-column:1/-1; text-align:center; color:var(--text-secondary);">' + emptyText + '</div>'; 
         }
         return; 
     }

     const tmpl = document.getElementById(templateId);
     if (!tmpl) {
         console.error('[MZSMB] Template not found:', templateId);
         return;
     }

     // --- Pagination Logic (skip for Grid) ---
     const totalItems = items.length;
     const totalPages = Math.ceil(totalItems / LIST_PAGE_SIZE);
     const isGrid = templateId === 'tmpl-grid' || templateId === 'tmpl-inventory';
     const needsPagination = !isGrid && totalItems > LIST_PAGE_SIZE;

     // Get or initialize current page
     let currentPage = _listPageState.get(containerId) || 0;
     // Clamp to valid range
     if (currentPage >= totalPages) currentPage = totalPages - 1;
     if (currentPage < 0) currentPage = 0;
     _listPageState.set(containerId, currentPage);

     // Calculate visible items (only slice if pagination is needed)
     let visibleItems;
     if (needsPagination) {
         const startIdx = currentPage * LIST_PAGE_SIZE;
         const endIdx = Math.min(startIdx + LIST_PAGE_SIZE, totalItems);
         visibleItems = items.slice(startIdx, endIdx);
     } else {
         visibleItems = items; // Show all items (e.g., for Grid)
     }

     // --- Render Function for Items ---
     const renderItems = (itemsToRender) => {
          const listPath = container.getAttribute('data-bind-list-fullpath') || container.getAttribute('data-bind-list') || '';
          const isQuestSource = listPath.includes('Quests') || listPath.includes('quest');
         itemsToRender.forEach(item => {
             let lastUpdated = ''; let title = '', desc = '', qty = '', difficulty = '', reward = '', status = '';

             // Extraction Logic
             if (shouldFlatten) {
                  // Item is an object from flatten()
                  const summary = getItemSummary(item);
                  title = summary.name; // Use name as title
