function renderFFOverviewV23(stat) {
    const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
    const numberAt = (path) => {
        const raw = getV(stat, path, null);
        if (raw === null || raw === undefined || raw === '' || raw === '???') return null;
        const value = Number(raw);
        return Number.isFinite(value) ? value : null;
    };
    const shown = (value) => value === null ? '—' : String(Number.isInteger(value) ? value : Math.round(value * 10) / 10);
    const write = (id, value) => { const element = document.getElementById(id); if (element) element.textContent = value; };

    const avatar = document.querySelector('.ff25-avatar-image');
    const avatarPlaceholder = document.querySelector('.ff25-avatar-placeholder');
    if (avatarPlaceholder) avatarPlaceholder.style.display = avatar && avatar.style.display === 'block' ? 'none' : 'flex';

    document.querySelectorAll('[data-ff25-cur]').forEach(statRow => {
        const current = numberAt(statRow.getAttribute('data-ff25-cur'));
        const maximum = numberAt(statRow.getAttribute('data-ff25-max'));
        const currentElement = statRow.querySelector('.ff25-stat-current');
        const maximumElement = statRow.querySelector('.ff25-stat-max');
        const fill = statRow.querySelector('.ff25-stat-fill');
        if (currentElement) currentElement.textContent = shown(current);
        if (maximumElement) maximumElement.textContent = shown(maximum);
        if (fill) fill.style.height = current !== null && maximum !== null && maximum > 0 ? clamp(current / maximum * 100, 0, 100) + '%' : '0%';
    });

    const hph = getV(stat, 'Narrative.Scene.HPH.player', null);
    const hphElement = document.getElementById('ff25-hph');
    const lowerGrid = document.getElementById('ff25-lower');
    const hasHph = Boolean(hph && typeof hph === 'object');
    if (hphElement) hphElement.style.display = hasHph ? '' : 'none';
    if (lowerGrid) lowerGrid.classList.toggle('ff25-no-hph', !hasHph);
    if (!hasHph) return;

    const bladder = numberAt('Narrative.Scene.HPH.player.Physiology.Bladder');
    const arousal = numberAt('Narrative.Scene.HPH.player.Physiology.Arousal');
    const erection = numberAt('Narrative.Scene.HPH.player.Physiology.ErectionLevel') ?? numberAt('Narrative.Scene.HPH.player.Physiology.ErectionCapacity');
    const semen = numberAt('Narrative.Scene.HPH.player.Physiology.SemenMl');
    const semenMax = numberAt('Narrative.Scene.HPH.player.Physiology.SemenCapacityMl');
    const length = numberAt('Narrative.Scene.HPH.player.Penis.LengthCm');
    const girth = numberAt('Narrative.Scene.HPH.player.Penis.GirthCm');

    const bladderLevel = bladder === null ? 0 : clamp(bladder, 0, 10);
    const arousalLevel = arousal === null ? 0 : clamp(arousal, 0, 10);
    const erectionLevel = erection === null ? 0 : clamp(erection, 0, 10);
    const bladderFill = document.getElementById('ff25-bladder-fill');
    const arousalFill = document.getElementById('ff25-arousal-fill');
    const erectionFill = document.getElementById('ff25-erection-fill');
    if (bladderFill) bladderFill.style.height = bladderLevel * 10 + '%';
    if (arousalFill) arousalFill.style.height = arousalLevel * 10 + '%';
    if (erectionFill) erectionFill.style.height = erectionLevel * 10 + '%';
    write('ff25-bladder-value', shown(bladder));
    write('ff25-arousal-value', shown(arousal));
    write('ff25-erection-value', shown(erection));
    write('ff25-semen-value', shown(semen));
    write('ff25-length-value', shown(length));
    write('ff25-girth-value', shown(girth));

    const semenFill = document.getElementById('ff25-semen-fill');
    const semenRatio = semen !== null && semenMax !== null && semenMax > 0 ? clamp(semen / semenMax, 0, 1) : 0;
    if (semenFill) semenFill.style.height = semenRatio * 100 + '%';
}

let _selectedOutfitOwnerPath = 'Mainchar';
let _outfitMoveInFlight = false;
const OUTFIT_SLOT_ORDER = { Head: 0, Torso: 1, Legs: 2, Feet: 3, Extra: 4 };
const OUTFIT_LAYER_ORDER = { Underwear: 0, Base: 1, Outerwear: 2 };

function outfitOwners(stat) {
    const owners = [];
    if (stat && stat.Mainchar) {
        owners.push({ path: 'Mainchar', name: String(getV(stat.Mainchar, 'Name', 'Main Character')) });
    }
    const familiars = stat && stat.Familiar && typeof stat.Familiar === 'object' ? stat.Familiar : {};
    for (const [key, member] of Object.entries(familiars)) {
        const shownName = String(getV(member, 'Name', key) || key);
        owners.push({ path: 'Familiar.' + key, name: shownName });
    }
    return owners;
}

function normalizedOutfitForDisplay(owner) {
    const outfit = owner && owner.Outfit && typeof owner.Outfit === 'object' ? owner.Outfit : {};
    return {
        Initialized: Boolean(outfit.Initialized),
        Worn: outfit.Worn && typeof outfit.Worn === 'object' ? outfit.Worn : {},
        Wardrobe: outfit.Wardrobe && typeof outfit.Wardrobe === 'object' ? outfit.Wardrobe : {},
    };
}

function outfitSortEntries(record) {
    return Object.entries(record || {}).sort((left, right) => {
        const a = left[1] || {};
        const b = right[1] || {};
        return (OUTFIT_SLOT_ORDER[a.Slot] ?? 99) - (OUTFIT_SLOT_ORDER[b.Slot] ?? 99)
            || (OUTFIT_LAYER_ORDER[a.Layer] ?? 99) - (OUTFIT_LAYER_ORDER[b.Layer] ?? 99)
            || String(a.Name || left[0]).localeCompare(String(b.Name || right[0]), 'ru');
    });
}

function appendOutfitBadge(parent, value) {
    if (!value) return;
    const badge = document.createElement('span');
    badge.className = 'outfit-badge';
    badge.textContent = String(value);
    parent.appendChild(badge);
}

function renderOutfitBucket(container, record, bucket) {
    if (!container) return;
    container.innerHTML = '';
    const entries = outfitSortEntries(record);
    if (!entries.length) {
        const empty = document.createElement('div');
        empty.className = 'outfit-empty';
        empty.textContent = bucket === 'Worn' ? 'Одежда ещё не зафиксирована' : 'Нет запасной одежды';
        container.appendChild(empty);
        return;
    }

    for (const [key, rawItem] of entries) {
        const item = rawItem && typeof rawItem === 'object' ? rawItem : {};
        const card = document.createElement('div');
        card.className = 'outfit-item';

        const main = document.createElement('div');
        main.className = 'outfit-item-main';
        const name = document.createElement('div');
        name.className = 'outfit-item-name';
        name.textContent = String(item.Name || key);
        const badges = document.createElement('div');
        badges.className = 'outfit-badges';
        appendOutfitBadge(badges, item.Slot || 'Extra');
        appendOutfitBadge(badges, item.Layer || 'Base');
        if (item.Slot === 'Extra') appendOutfitBadge(badges, item.Placement);
        main.appendChild(name);
        main.appendChild(badges);

        const action = document.createElement('button');
        action.type = 'button';
        action.className = 'outfit-action';
        action.textContent = bucket === 'Worn' ? 'Снять' : 'Надеть';
        action.onclick = event => {
            event.stopPropagation();
            moveOutfitItem(_selectedOutfitOwnerPath, bucket, key);
        };

        card.appendChild(main);
        card.appendChild(action);

        const identityParts = [item.Color, item.Material].filter(Boolean).map(String);
        const descriptionParts = [];
        if (identityParts.length) descriptionParts.push(identityParts.join(' · '));
        if (item.Appearance) descriptionParts.push(String(item.Appearance));
        if (descriptionParts.length) {
            const detail = document.createElement('div');
            detail.className = 'outfit-item-detail';
            detail.textContent = descriptionParts.join(' — ');
            card.appendChild(detail);
        }

        const stateParts = [item.Condition, item.Arrangement].filter(Boolean).map(String);
        if (stateParts.length) {
            const state = document.createElement('div');
            state.className = 'outfit-item-detail outfit-item-state';
            state.textContent = stateParts.join(' · ');
            card.appendChild(state);
        }
        container.appendChild(card);
    }
}

function uniqueOutfitKey(record, preferred) {
    if (!Object.prototype.hasOwnProperty.call(record, preferred)) return preferred;
    let index = 2;
    while (Object.prototype.hasOwnProperty.call(record, preferred + '_' + index)) index++;
    return preferred + '_' + index;
}

async function moveOutfitItem(ownerPath, fromBucket, itemKey) {
    if (!_lastStatData || _outfitMoveInFlight) return;
    _outfitMoveInFlight = true;
    try {
        const stat = JSON.parse(JSON.stringify(_lastStatData));
        const owner = resolvePathObject(stat, ownerPath, false);
        if (!owner) return;
        if (!owner.Outfit || typeof owner.Outfit !== 'object') owner.Outfit = { Initialized: false, Worn: {}, Wardrobe: {} };
        const outfit = owner.Outfit;
        if (!outfit.Worn || typeof outfit.Worn !== 'object') outfit.Worn = {};
        if (!outfit.Wardrobe || typeof outfit.Wardrobe !== 'object') outfit.Wardrobe = {};
        const source = fromBucket === 'Worn' ? outfit.Worn : outfit.Wardrobe;
        const target = fromBucket === 'Worn' ? outfit.Wardrobe : outfit.Worn;
        const item = source[itemKey];
        if (!item || typeof item !== 'object') return;

        if (fromBucket === 'Wardrobe' && item.Slot !== 'Extra') {
            for (const [wornKey, wornItem] of Object.entries(outfit.Worn)) {
                if (!wornItem || wornItem.Slot !== item.Slot || wornItem.Layer !== item.Layer) continue;
                const returnKey = uniqueOutfitKey(outfit.Wardrobe, wornKey);
                outfit.Wardrobe[returnKey] = JSON.parse(JSON.stringify(wornItem));
                delete outfit.Worn[wornKey];
            }
        }

        const destinationKey = uniqueOutfitKey(target, itemKey);
        target[destinationKey] = JSON.parse(JSON.stringify(item));
        delete source[itemKey];
        outfit.Initialized = true;
        await saveStatData(stat);
    } finally {
        _outfitMoveInFlight = false;
    }
}

function renderOutfitPanel(stat) {
    const tabs = document.getElementById('outfit-owner-tabs');
    const status = document.getElementById('outfit-status');
    const wornList = document.getElementById('outfit-worn-list');
    const wardrobeList = document.getElementById('outfit-wardrobe-list');
    if (!tabs || !wornList || !wardrobeList) return;

    const owners = outfitOwners(stat);
    if (!owners.some(owner => owner.path === _selectedOutfitOwnerPath)) {
        _selectedOutfitOwnerPath = owners[0]?.path || 'Mainchar';
    }
    tabs.innerHTML = '';
    for (const owner of owners) {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'outfit-owner-btn' + (owner.path === _selectedOutfitOwnerPath ? ' active' : '');
        button.textContent = owner.name;
        button.onclick = () => {
            _selectedOutfitOwnerPath = owner.path;
            renderOutfitPanel(stat);
        };
        tabs.appendChild(button);
    }

    const owner = resolvePathObject(stat, _selectedOutfitOwnerPath, false);
    const outfit = normalizedOutfitForDisplay(owner);
    if (status) status.textContent = outfit.Initialized ? 'Наряд зафиксирован' : 'Будет создан моделью при следующем RP-ходе';
    const wornCount = document.getElementById('outfit-worn-count');
    const wardrobeCount = document.getElementById('outfit-wardrobe-count');
    if (wornCount) wornCount.textContent = String(Object.keys(outfit.Worn).length);
    if (wardrobeCount) wardrobeCount.textContent = String(Object.keys(outfit.Wardrobe).length);
    renderOutfitBucket(wornList, outfit.Worn, 'Worn');
    renderOutfitBucket(wardrobeList, outfit.Wardrobe, 'Wardrobe');
}

async function updateStatusPanel(gameData) {
    if (!gameData || !gameData.stat_data) return;
    const stat = gameData.stat_data;

    // Phase 1: Update Unmapped (Global) Bindings
    updateBindingsIn(document.body, stat, stat);
    updateLorebookContent(document.body); // Async

    // Phase 2: Update Mapped Blocks (Collections/Records)
    const containers = document.querySelectorAll('[data-bind-root]');
    for (const container of containers) {
         const rootKey = container.getAttribute('data-bind-root');
         const templateId = container.getAttribute('data-template');
         if (rootKey && templateId) {
              const rootData = getV(stat, rootKey, null);
              // Pass global 'stat' as rootData
              renderBlock(container.id, rootData, templateId, stat);
              updateLorebookContent(container); // Async
         }
    }
    renderFFSMState(stat.Narrative);
    renderFFOverviewV23(stat);
    renderOutfitPanel(stat);
}

// --- MVU Event Logic (Native) ---
let _lastStatData = null;
let _lastSaveTime = 0;
let _lastRenderedBranchToken = '';

const parseMessageIdFromName = (name) => {
    if (!name || typeof name !== 'string' || !name.includes('message')) return -1;
    const match = name.match(/message.*?(\d+)/i);
    if (!match) return -1;
    const parsed = Number(match[1]);
    return Number.isFinite(parsed) && parsed >= 0 ? parsed : -1;
};

const resolveApiTarget = () => {
    const candidates = [window];
    try { if (window.parent && window.parent !== window) candidates.push(window.parent); } catch (e) {}
    try { if (window.top && !candidates.includes(window.top)) candidates.push(window.top); } catch (e) {}
    return candidates.find(target =>
        typeof target?.waitGlobalInitialized === 'function' ||
        typeof target?.getVariables === 'function' ||
        target?.Mvu
    ) || window;
};

// The panel iframe and the Core script iframe may each receive their own MVU
// bridge. Therefore the first scope exposing Mvu is not necessarily the scope
// where Core published FFMVU. Resolve Core independently across frame scopes.
const resolveCoreApi = () => {
    const candidates = [window];
    try { if (window.parent && window.parent !== window) candidates.push(window.parent); } catch (e) {}
    try { if (window.top && !candidates.includes(window.top)) candidates.push(window.top); } catch (e) {}
    for (const candidate of candidates) {
        try {
            if (typeof candidate?.FFMVU?.commitExternalState === 'function') return candidate.FFMVU;
        } catch (e) {}
    }
    return null;
};

const resolveCurrentMessageId = () => {
    const target = resolveApiTarget();
    for (const candidate of [target, window]) {
        try {
            if (typeof candidate.getLastMessageId === 'function') {
                const id = Number(candidate.getLastMessageId());
                if (Number.isFinite(id) && id >= 0) return id;
            }
            const chat = candidate.SillyTavern?.chat || candidate.SillyTavern?.getContext?.()?.chat;
            if (Array.isArray(chat) && chat.length) return chat.length - 1;
        } catch (e) {}
    }
    if (typeof getCurrentMessageId === 'function') {
        const id = Number(getCurrentMessageId());
        if (Number.isFinite(id) && id >= 0) return id;
    }
    const frameId = parseMessageIdFromName(window.name);
    if (frameId >= 0) return frameId;
    const parentFrameId = parseMessageIdFromName(window.parent && window.parent.name);
    return parentFrameId >= 0 ? parentFrameId : -1;
};

const activeMessageContext = () => {
    const messageId = resolveCurrentMessageId();
    return { type: 'message', message_id: messageId >= 0 ? messageId : 'latest' };
};

const activeBranchToken = () => {
    const target = resolveApiTarget();
    const messageId = resolveCurrentMessageId();
    try {
        const context = target.SillyTavern?.getContext?.();
        const chat = target.SillyTavern?.chat || context?.chat;
        const message = Array.isArray(chat) ? chat[messageId] : null;
        const swipe = message?.swipe_id ?? message?.swipeId ?? 0;
        const chatId = target.SillyTavern?.getCurrentChatId?.() ?? context?.chatId ?? '';
        return String(chatId) + ':' + messageId + ':' + swipe;
    } catch (e) {
        return String(messageId);
    }
};

const readActiveStatData = async () => {
    const target = resolveApiTarget();
    const context = activeMessageContext();
    try {
        const mvuData = target.Mvu?.getMvuData?.(context);
        if (mvuData?.stat_data) return JSON.parse(JSON.stringify(mvuData.stat_data));
    } catch (e) {}
    try {
        const vars = target.getVariables?.(context) || window.getVariables?.(context);
        if (vars?.stat_data) return JSON.parse(JSON.stringify(vars.stat_data));
    } catch (e) {}
    try {
        const messageId = resolveCurrentMessageId();
        if (messageId >= 0 && typeof getChatMessages === 'function') {
            const messages = await getChatMessages(messageId);
            if (messages?.[0]?.data?.stat_data) return JSON.parse(JSON.stringify(messages[0].data.stat_data));
        }
    } catch (e) {}
    return null;
};

const refreshFromMvu = async (force = false) => {
    const latestStatData = await readActiveStatData();
    if (!latestStatData) return;
    const modal = document.getElementById('portrait-mode-modal');
    if (modal && modal.style.display === 'flex' && !force) return;
    if (!force && Date.now() - _lastSaveTime < 1200) return;
    const branch = activeBranchToken();
    const isDifferent = JSON.stringify(latestStatData) !== JSON.stringify(_lastStatData);
    if (force || isDifferent || branch !== _lastRenderedBranchToken) {
        await updateStatusPanel({ stat_data: latestStatData });
        _lastStatData = JSON.parse(JSON.stringify(latestStatData));
        _lastRenderedBranchToken = branch;
    }
};

const initMvuConnection = async () => {
    const target = resolveApiTarget();
    if (typeof target.waitGlobalInitialized === 'function') {
        try { await target.waitGlobalInitialized('Mvu'); } catch (e) {}
    }

    await refreshFromMvu(true);

    const scheduleRefresh = () => setTimeout(() => refreshFromMvu(true), 0);
    const Mvu = target.Mvu;
    if (typeof target.eventOn === 'function' && Mvu?.events?.VARIABLE_UPDATE_ENDED) {
        target.eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, scheduleRefresh);
    }
    const events = target.tavern_events || {};
    const eventNames = ['MESSAGE_SWIPED', 'MESSAGE_DELETED', 'MESSAGE_EDITED', 'MESSAGE_UPDATED', 'MESSAGE_RECEIVED', 'MESSAGE_SENT', 'CHAT_CHANGED'];
    for (const eventName of [...new Set(eventNames.map(name => events[name]).filter(Boolean))]) {
        if (typeof target.eventOn === 'function') target.eventOn(eventName, scheduleRefresh);
    }

    setInterval(() => refreshFromMvu(false), 1200);
    return _lastStatData;
};



