// Strip internal runtime keys ($key, $raw, $meta) recursively before saving
function stripInternalKeys(obj) {
    if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return obj;
    for (const k of Object.keys(obj)) {
        if (k === '$key' || k === '$raw' || k === '$meta') {
            delete obj[k];
        } else {
            stripInternalKeys(obj[k]);
        }
    }
    return obj;
}

// Save Function
async function saveStatData(updatedStat) {
    if (!updatedStat) return false;
    const branchBefore = activeBranchToken();
    if (_lastRenderedBranchToken && branchBefore !== _lastRenderedBranchToken) {
        await refreshFromMvu(true);
        console.warn('[MZSMB] Save cancelled: active message or swipe changed.');
        return false;
    }

    const snapshot = JSON.parse(JSON.stringify(updatedStat));
    stripInternalKeys(snapshot);
    _lastSaveTime = Date.now();

    try {
        if (branchBefore !== activeBranchToken()) {
            await refreshFromMvu(true);
            return false;
        }

        // Core owns branch replay and snapshot hashes. Commit through it when
        // available so a deliberate panel edit is not mistaken for stale MVU
        // data on the next message.
        const core = resolveCoreApi();
        const messageId = resolveCurrentMessageId();
        if (!core || messageId < 0) throw new Error('FFMVU Core API not found; edit was not saved');
        const committedSnapshot = await core.commitExternalState(messageId, snapshot, 'external-edit');

        // Do not report an optimistic success unless Core wrote one coherent
        // state + projection + metadata transaction to this exact message.
        const stored = typeof core.readVariables === 'function' ? core.readVariables(messageId) : null;
        const storedMeta = stored?.ff_mvu_snapshot_meta;
        if (!stored || JSON.stringify(stored.stat_data) !== JSON.stringify(committedSnapshot) ||
            storedMeta?.Kind !== 'external-edit' || storedMeta?.MessageId !== messageId) {
            throw new Error('FFMVU Core did not confirm the external edit');
        }

        if (branchBefore !== activeBranchToken()) {
            await refreshFromMvu(true);
            return false;
        }

        _lastStatData = JSON.parse(JSON.stringify(committedSnapshot));
        _lastRenderedBranchToken = branchBefore;
        await updateStatusPanel({ stat_data: committedSnapshot });
        return true;
    } catch (error) {
        console.error('[MZSMB] saveStatData failed:', error);
        alert('Failed to save data: ' + error.message);
        return false;
    }
}

